data.code:
ContentInfo {
  contentType id-signedData,
  content     SignedData
}

SignedData {
  version           3,             -- always set to 3
  digestAlgorithms  one entry,
  encapContentInfo  EncapsulatedContentInfo,
  certificates      optional,
  crls              optional,
  signerInfos       one entry
}

EncapsulatedContentInfo {
  eContentType  the TAMP message type,
  eContent      the TAMP message
}
